namespace AllocationDiagnostic;

internal static class AllocationDiagnosticNames
{
    internal const int ArgumentCount = 1;
    internal const string Usage = "Usage: Erlang.AllocationDiagnostic newOutput.json";
    internal const string FreshOutput = "Output report must be new";
    internal const string RowSummary = " rows=";
    internal const string Module = "erlang";
    internal const string Function = "phash2";
    internal const string AlgorithmType = "Erlang.ErlangNativeHash";
    internal const string AlgorithmMethod = "Portable2";
    internal const string RegisteredFunctions = "functions";
    internal const string ExactWindow = "ExactOriginalFirstWindow";
    internal const string RegistryWindow = "OriginalRegistryWindow";
    internal const string PrebuiltWindow = "PrebuiltArgumentsRegistry";
    internal const string BodyWindow = "RegisteredBody";
    internal const string DirectWindow = "Portable2Delegate";
    internal const string ArgumentsWindow = "ArgumentConstructionOnly";
    internal const string Completed = "DiagnosticCompleted";
    internal const string Failed = "DiagnosticFailed";
    internal const string ProcessorCountVariable = "DOTNET_PROCESSOR_COUNT";
    internal const string TieredCompilationVariable = "DOTNET_TieredCompilation";
    internal const string TieredPgoVariable = "DOTNET_TieredPGO";
    internal const string LegacyTieredCompilationVariable = "COMPlus_TieredCompilation";
    internal const string LegacyTieredPgoVariable = "COMPlus_TieredPGO";
}

namespace AllocationDiagnostic;
internal static class AllocationDiagnosticParameters
{
    internal const int BinaryBytes = 4 * 1024 * 1024;
    internal const long FullRange = 4294967296;
    internal const int Samples = 16;
    internal const int BudgetBytes = 4096;
}

using AllocationDiagnostic;
using Erlang;
using System.Reflection;
using System.Security.Cryptography;
using System.Text.Json;
using System.Runtime.InteropServices;
if (args.Length != AllocationDiagnosticNames.ArgumentCount)
    throw new ArgumentException(AllocationDiagnosticNames.Usage);
if (File.Exists(args[0]))
    throw new IOException(AllocationDiagnosticNames.FreshOutput);
var rows=new List<object>();Exception? failure=null;
await using(var runtime=new ProcessRuntime()){
 var actor=runtime.Spawn(async context=>{
  try{
   var binary=new BitString(new byte[AllocationDiagnosticParameters.BinaryBytes]);
   await runtime.Modules.Call(context,AllocationDiagnosticNames.Module,AllocationDiagnosticNames.Function,binary,Term.I(AllocationDiagnosticParameters.FullRange));
   int thread=Environment.CurrentManagedThreadId;long before=GC.GetAllocatedBytesForCurrentThread();
   ValueTask<Term> pending=runtime.Modules.Call(context,AllocationDiagnosticNames.Module,AllocationDiagnosticNames.Function,binary,Term.I(AllocationDiagnosticParameters.FullRange));
   bool sync=pending.IsCompletedSuccessfully;Term result=pending.GetAwaiter().GetResult();long allocated=GC.GetAllocatedBytesForCurrentThread()-before;
   rows.Add(new{Kind=AllocationDiagnosticNames.ExactWindow,Sample=0,Bytes=allocated,StartingThread=thread,EndingThread=Environment.CurrentManagedThreadId,Synchronous=sync,Result=result.ToString()});
   var algorithm=typeof(ProcessRuntime).Assembly.GetType(AllocationDiagnosticNames.AlgorithmType,true)!.GetMethod(AllocationDiagnosticNames.AlgorithmMethod)!.CreateDelegate<Func<Term,uint>>();
   var field=typeof(ModuleRegistry).GetField(AllocationDiagnosticNames.RegisteredFunctions,BindingFlags.Instance|BindingFlags.NonPublic)!;var functions=(IDictionary<(string,string,int),ErlangFunction>)field.GetValue(runtime.Modules)!;var body=functions[(AllocationDiagnosticNames.Module,AllocationDiagnosticNames.Function,2)];Term[] args=[binary,Term.I(AllocationDiagnosticParameters.FullRange)];
   foreach(string kind in new[]{AllocationDiagnosticNames.RegistryWindow,AllocationDiagnosticNames.PrebuiltWindow,AllocationDiagnosticNames.BodyWindow,AllocationDiagnosticNames.DirectWindow,AllocationDiagnosticNames.ArgumentsWindow}){
    for(int i=0;i<AllocationDiagnosticParameters.Samples;i++){
     thread=Environment.CurrentManagedThreadId;before=GC.GetAllocatedBytesForCurrentThread();uint value=0;bool synchronous=true;
     if(kind==AllocationDiagnosticNames.DirectWindow)value=algorithm(binary);
     else if(kind==AllocationDiagnosticNames.ArgumentsWindow){Term[] created=[binary,Term.I(AllocationDiagnosticParameters.FullRange)];value=(uint)created.Length;GC.KeepAlive(created);}
     else {ValueTask<Term> call=kind==AllocationDiagnosticNames.BodyWindow?body(context,args):kind==AllocationDiagnosticNames.PrebuiltWindow?runtime.Modules.Call(context,AllocationDiagnosticNames.Module,AllocationDiagnosticNames.Function,args):runtime.Modules.Call(context,AllocationDiagnosticNames.Module,AllocationDiagnosticNames.Function,binary,Term.I(AllocationDiagnosticParameters.FullRange));synchronous=call.IsCompletedSuccessfully;result=call.GetAwaiter().GetResult();value=(uint)((Integer)result).Value;}
     allocated=GC.GetAllocatedBytesForCurrentThread()-before;rows.Add(new{Kind=kind,Sample=i,Bytes=allocated,StartingThread=thread,EndingThread=Environment.CurrentManagedThreadId,Synchronous=synchronous,Hash=value});
    }
   }
  }catch(Exception ex){failure=ex;}return Nil.Value;
 });await actor.Completion;
}
var report=new{Status=failure is null?AllocationDiagnosticNames.Completed:AllocationDiagnosticNames.Failed,Rows=rows,Failure=failure?.ToString(),Framework=RuntimeInformation.FrameworkDescription,Architecture=RuntimeInformation.ProcessArchitecture.ToString(),OS=RuntimeInformation.OSDescription,Environment=new[]{AllocationDiagnosticNames.ProcessorCountVariable,AllocationDiagnosticNames.TieredCompilationVariable,AllocationDiagnosticNames.TieredPgoVariable,AllocationDiagnosticNames.LegacyTieredCompilationVariable,AllocationDiagnosticNames.LegacyTieredPgoVariable}.ToDictionary(x=>x,System.Environment.GetEnvironmentVariable),Assemblies=new[]{typeof(ProcessRuntime).Assembly,typeof(Term).Assembly}.Select(a=>new{a.Location,a.ManifestModule.ModuleVersionId,Sha256=Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(a.Location)))}),UnchangedBudget=AllocationDiagnosticParameters.BudgetBytes,BinaryBytes=AllocationDiagnosticParameters.BinaryBytes,SourceOrBudgetChanged=false,NativeExecuted=false};await File.WriteAllTextAsync(args[0],JsonSerializer.Serialize(report,new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine(report.Status+AllocationDiagnosticNames.RowSummary+rows.Count);if(failure is not null)return 1;return 0;
